/* Auto-generated 11x11 bitmap glyphs for all 11172 modern Hangul
 * syllables (U+AC00 to U+D7A3) plus the 51 standalone compatibility
 * jamo (U+3131 to U+3163, used to show an in-progress consonant or
 * vowel before it combines into a full syllable), extracted from
 * Galmuri11 (see third_party/galmuri-font/, SIL Open Font License
 * 1.1) by tools/gen_hangul_font.py. Do not hand-edit -- regenerate
 * with that script if the font ever changes.
 *
 * Each glyph is 11 rows of u16, MSB-aligned exactly like
 * font_latin_data.h's Latin glyphs -- see that header for the bit
 * layout. Index font8x8_ko with (codepoint - KO_SYLLABLE_BASE), and
 * font8x8_ko_jamo with (codepoint - KO_JAMO_BASE). (Table names kept
 * as font8x8_ko/font8x8_ko_jamo for now even though glyphs are 11x11
 * -- renaming them would just be churn across font_ko.h's call
 * sites for zero behavioral change.)
 *
 * The 11172-syllable table is 245784 bytes raw. Since 1.1-alpha-14 it is NOT in the kernel image any more (it was 62,755
 * bytes of it, and the kernel had run out of room): it lives in the FONT PACK in the system area of the disk image
 * (tools/gen_font_pack.py, kernel/fontpack.h) and fontpack_boot() inflates it to MW_KFONT_ADDR (memmap.h) right after the
 * heap exists and before the first frame, so font8x8_ko below is a pointer into high memory, not a table in the image.
 * KO_FONT_CHECKSUM is what the pack's Galmuri11 table must hash to. The 51 jamo stay as they are. */

#define KO_SYLLABLE_COUNT 11172
#define KO_SYLLABLE_BASE  0xAC00
#define KO_JAMO_COUNT 51
#define KO_JAMO_BASE  0x3131

#define KO_FONT_RAW_BYTES    245784u
#define KO_FONT_CHECKSUM     0x6AE3D579u   /* FNV-1a over the 11172 x 11 x u16 syllable bytes */

#define font8x8_ko ((const u16 (*)[11])MW_KFONT_ADDR)

